import{_ as s,o as a,c as t,a3 as n}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contributing | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/contributing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/contributing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/contributing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/contributing"}]]},"headers":[],"relativePath":"xclang/dev/contributing.md","filePath":"en/xclang/dev/contributing.md","lastUpdated":1791516064000}'),i={name:"xclang/dev/contributing.md"};function o(l,e,c,r,p,d){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>xclang is a small repository that drives a large build: LLVM, built six times with PGO and ThinLTO, plus the runtimes of every target. Most contributions are to the scripts, the build integrations, the tests or the docs. Most of them are checked on CI, not on a laptop.</p><h2 id="where-things-are" tabindex="-1">Where Things Are <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;Where Things Are&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>toolchain/         the build pipeline, TypeScript run by Node 24:</span></span>
<span class="line"><span>                   bootstrap.ts, runtimes.ts (with sysroot.ts),</span></span>
<span class="line"><span>                   toolchain.ts, package.ts, licenses.ts, fetch.ts;</span></span>
<span class="line"><span>                   common.ts, what every script shares (versions,</span></span>
<span class="line"><span>                   pinned sources, targets)</span></span>
<span class="line"><span>  cmake/           caches/, what each LLVM build is: runtimes, the host</span></span>
<span class="line"><span>                   toolchain, the instrumented one, the ASan libclang;</span></span>
<span class="line"><span>                   toolchain.cmake, building for a target with an</span></span>
<span class="line"><span>                   xclang tree</span></span>
<span class="line"><span>  config/          the per-target clang config files</span></span>
<span class="line"><span>  pgo/             the training (train.ts, its corpus) and remap.txt</span></span>
<span class="line"><span>  launcher/        alias.c, the launcher behind every name of llvm.exe</span></span>
<span class="line"><span>  licenses/        license texts the archives carry that no source</span></span>
<span class="line"><span>                   ships (licenses.ts)</span></span>
<span class="line"><span>  musl/            the patches of musl&#39;s security advisories, applied to</span></span>
<span class="line"><span>                   its release (sysroot.ts)</span></span>
<span class="line"><span>cli/               the xclang command, in Rust; its SDK version table,</span></span>
<span class="line"><span>                   sdk-versions.json; cli.ts builds it</span></span>
<span class="line"><span>patches/           changes to LLVM, a directory and a README each</span></span>
<span class="line"><span>packages/          what xclang&#39;s users build with (packages/README.md):</span></span>
<span class="line"><span>  bazel/           the Bazel module; bazel.ts makes its registry archive</span></span>
<span class="line"><span>  cmake/           the CMake package (find_package, toolchain file,</span></span>
<span class="line"><span>                   FetchContent download)</span></span>
<span class="line"><span>  conda/           the activation scripts of the conda packages; conda.ts</span></span>
<span class="line"><span>                   makes the packages</span></span>
<span class="line"><span>tests/             one directory per thing tested, its script beside its</span></span>
<span class="line"><span>                   fixtures:</span></span>
<span class="line"><span>  toolchain/       smoke.ts, a host&#39;s toolchain archive on its host</span></span>
<span class="line"><span>  libclang/        libclang.ts and a tool on libclang</span></span>
<span class="line"><span>  cmake/           cmake.ts and a project on the CMake package</span></span>
<span class="line"><span>  bazel/           bazel.ts and cross.ts, and a workspace on the module</span></span>
<span class="line"><span>  sdk/             msvc.ts and macos.ts, the targets of the vendor SDKs</span></span>
<span class="line"><span>  cli/             cli.ts and cargo.ts, the xclang command</span></span>
<span class="line"><span>  release/         repack.ts, a repack against the release it repacks</span></span>
<span class="line"><span>  docs/            docs.ts, the docs against examples/ and examples.yml</span></span>
<span class="line"><span>  bench/           bench.ts and report.ts, compile speed</span></span>
<span class="line"><span>  lib/             what the others share: a host&#39;s archives unpacked</span></span>
<span class="line"><span>                   (archives.ts), programs run on their target</span></span>
<span class="line"><span>                   (on-target.ts)</span></span>
<span class="line"><span>examples/          the projects the docs show, built by examples.yml</span></span>
<span class="line"><span>docs/en/           this site</span></span>
<span class="line"><span>.github/workflows/ CI: release.yml and its stage-*.yml build a release;</span></span>
<span class="line"><span>                   test-*.yml and cli.yml test it, and every push</span></span>
<span class="line"><span>                   (checks.yml); published.yml follows publishing;</span></span>
<span class="line"><span>                   weekly.yml runs every week</span></span></code></pre></div><p>The <a href="./release-build">build pipeline</a> has the stages and the workflows.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>The builds need CI-sized machines. A full release run is about three hours on GitHub-hosted runners, and the toolchain stage about two hours per host. Run them on CI, on a branch of your own:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=runtimes,instrumented,train,toolchain,asan,package,test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>(The workflow must be on <code>main</code> for <code>gh workflow run</code>; the branch&#39;s copy of it is what runs.) A push runs checks.yml: the tests of what it changed, against the latest release, in minutes (<a href="./testing#when-tests-run">testing</a>).</p><p><code>reuse-run</code>, with <code>runtimes-run</code> and <code>profile-run</code>, takes the artifacts of a stage from an earlier run instead of building them again. A toolchain without PGO is enough for most A/B checks. <code>pixi run &lt;task&gt;</code> runs a stage the way CI does (pixi.toml), on a machine that can take it.</p><p>These are cheap locally:</p><ul><li><code>npm install &amp;&amp; npm run check</code>: TypeScript type checks of every script: <code>toolchain/</code>, <code>tests/</code>, and those of <code>cli/</code> and <code>packages/</code>.</li><li><code>node tests/docs/docs.ts</code>: the code blocks of the docs against <code>examples/</code>, the links, and the status words.</li><li><code>cd cli &amp;&amp; cargo test</code>: the unit tests of the xclang command.</li><li>A patch: <code>patch -p1 -F0 --dry-run</code> against the LLVM release source, and compiling the patched file against the headers of a release (<a href="./llvm-patches">patching LLVM</a>).</li><li>Anything against a released toolchain: unpack an archive and use it.</li></ul><h2 id="style" tabindex="-1">Style <a class="header-anchor" href="#style" aria-label="Permalink to &quot;Style&quot;">​</a></h2><ul><li>Scripts are TypeScript on Node, not Python or shell. Comments are <code>///</code> lines.</li><li>Docs and comments say what is and why, plainly. No marketing adjectives; reasons instead.</li><li>Commit subjects are <code>&lt;area&gt;: &lt;what changed&gt;</code> (<code>bazel: ...</code>, <code>docs: ...</code>, <code>patches: ...</code>). The body says why.</li><li>Every user-visible change gets a line in the Unreleased section of CHANGELOG.md.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Every change comes with the check that shows it works, on the hosts it touches. What each test covers is in <a href="./testing">testing</a>.</p><table tabindex="0"><thead><tr><th>change</th><th>test</th></tr></thead><tbody><tr><td>the toolchain, the runtimes, a patch</td><td><code>tests/toolchain/smoke.ts</code> (the <code>test</code> stage of release.yml, every host)</td></tr><tr><td>the config files</td><td><code>tests/toolchain/smoke.ts</code>, <code>tests/sdk</code> (test-archives.yml, test-sdk.yml, on a push)</td></tr><tr><td>libclang</td><td><code>tests/libclang/libclang.ts</code></td></tr><tr><td>the CMake package</td><td><code>tests/cmake</code> (test-cmake.yml)</td></tr><tr><td>the Bazel module</td><td><code>tests/bazel</code>, <code>tests/bazel/bazel.ts</code>, <code>tests/bazel/cross.ts</code> (test-bazel.yml)</td></tr><tr><td>the MSVC and macOS targets</td><td><code>tests/sdk/msvc.ts</code>, <code>tests/sdk/macos.ts</code> (test-sdk.yml)</td></tr><tr><td>the xclang command</td><td><code>tests/cli/cli.ts</code>, <code>tests/cli/cargo.ts</code> (cli.yml)</td></tr><tr><td>the commands of the docs, <code>examples/</code></td><td>examples.yml</td></tr><tr><td>a program run on another target</td><td><code>tests/lib/on-target.ts</code> (on-target.yml): write its <code>programs.json</code></td></tr></tbody></table><h2 id="the-docs" tabindex="-1">The Docs <a class="header-anchor" href="#the-docs" aria-label="Permalink to &quot;The Docs&quot;">​</a></h2><p>The docs are <code>docs/en/&lt;group&gt;/&lt;page&gt;.md</code>, published to <a href="https://docs.clice.io/xclang" target="_blank" rel="noreferrer">docs.clice.io/xclang</a> by the sync action of clice-io/docs when <code>main</code> changes. <code>docs/en/sidebar.yaml</code> orders the pages and gives their sidebar labels, one to three words each.</p><ul><li>Every page is one kind: a guide, an integration how-to, a feature page, a reference page or a design note.</li><li>What is not in a release has one row in the <a href="./../design/roadmap">roadmap</a>, with one of its six status words. Other pages link the status word to that row, and end with <code>## Not Yet Supported</code> and <code>## Known Limitations</code>.</li><li>Measurements live in <a href="./../design/pgo">PGO</a> and <a href="./../features/thinlto-cache">the ThinLTO cache</a>, each with its release. Test names and CI runs live in <a href="./testing">testing</a>.</li><li>A code block under <code>&lt;!-- file: &lt;path&gt; --&gt;</code> must be that file of the repository, and one under <code>&lt;!-- excerpt: &lt;path&gt; --&gt;</code> consecutive lines of it. A command block is an excerpt of a step of examples.yml, or says why CI does not run it (<code>&lt;!-- not run: &lt;why&gt; --&gt;</code>). <code>tests/docs/docs.ts</code> checks all three.</li><li>An example of a page is a directory of <code>examples/</code>, with the <code>pixi.toml</code> of the quick start, and an <code>expected.txt</code> for what its program prints.</li></ul><p>To preview, copy <code>docs/en</code> into a checkout of <a href="https://github.com/clice-io/docs" target="_blank" rel="noreferrer">clice-io/docs</a> as <code>en/xclang</code> and run its VitePress build (<code>npm install &amp;&amp; npm run build</code>). The build fails on a dead link.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Bugs and questions go to <a href="https://github.com/clice-io/xclang/issues" target="_blank" rel="noreferrer">GitHub issues</a>. A bug in clang, lld or libc++ itself is reported upstream, to LLVM; xclang carries a fix as a patch until upstream has one. For security issues, see <a href="https://github.com/clice-io/xclang/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p>`,23)])])}const u=s(i,[["render",o]]);export{g as __pageData,u as default};
